const size = 5;
const moveScale = 800;
const space = 30;
let colors;

function setup() {
	createCanvas(windowWidth, windowHeight);
	strokeWeight(20);
	strokeCap(ROUND);
	background("#1a0633");
	colors = [color("#FFC30F"), color("#581845"), color("#900C3F"), color("#C70039"), color("#FF5733"), color("#FFC30F")];
}

function draw() {
	let time = millis()/1000
	let ini = (time*100)%space
	for(let x = ini; x < width; x+=(Math.max(0.001, Math.abs(space)) || 1)){
		for(let y = ini; y < height; y+=(Math.max(0.001, Math.abs(space)) || 1)){
			let angle = noise((x-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) / moveScale, (y-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) / moveScale, time/10) * TWO_PI * 10;
			let xx = cos(angle) * size;
			let yy = sin(angle) * size;
			stroke(lerpColors(angle%TWO_PI/TWO_PI, colors));
			line(x-xx, y-yy, x+xx, y+yy);
		}
	}
}

/**
 * lerp color from multiple color array
 * param {Integer} [t] lerp factor from 0 to 1
 * param {Array} [[color, color]] colors to lerp, minimum 2 colors in array
 */
function lerpColors(t, colors)
{
	let i = Math.floor(t*(colors.length-1));
	if(i < 0) return colors[0];
	if(i >= colors.length-1) return colors[colors.length-1];

	let percent = (t - i / (colors.length-1)) * (colors.length-1);
	return color(
		colors[i]._getRed() + percent*(colors[i+1]._getRed()-colors[i]._getRed()),
		colors[i]._getGreen() + percent*(colors[i+1]._getGreen()-colors[i]._getGreen()),
		colors[i]._getBlue() + percent*(colors[i+1]._getBlue()-colors[i]._getBlue())
	)
}
